from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marker = next(v for v in counts if v != bg)
    out = [row[:] for row in grid]

    # Complete every sampled horizontal stroke (three or more marker cells).
    strokes = []
    for r, row in enumerate(grid):
        xs = [c for c, value in enumerate(row) if value == marker]
        if len(xs) >= 3:
            strokes.append((r, xs))
            for c in range(xs[0], xs[-1] + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2

    # The topmost and bottommost sampled strokes define a rectangular frame;
    # connect their leftmost and rightmost endpoints with vertical rails.
    if len(strokes) >= 2:
        top_r, top_xs = strokes[0]
        bottom_r, bottom_xs = strokes[-1]
        left = min(top_xs[0], bottom_xs[0])
        right = max(top_xs[-1], bottom_xs[-1])
        for c in (left, right):
            for r in range(top_r, bottom_r + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out
